        for (int r = 0; r < m / 2; ++r) {
            for (int c = 0; c < n / 2; ++c) {
                int ones = grid[r][c] + grid[m - 1 - r][c] + grid[r][n - 1 - c] + grid[m - 1 - r][n - 1 - c];
                ans += min(ones, 4 - ones);
            }
