        int ones_pairs = 0;

        if (m % 2 == 1) {
            int mid_r = m / 2;
            for (int c = 0; c < n / 2; ++c) {
                if (grid[mid_r][c] != grid[mid_r][n - 1 - c]) {
                    diff++;
                } else if (grid[mid_r][c] == 1) {
                    ones_pairs++;
                }
            }
        }

        if (n % 2 == 1) {
            int mid_c = n / 2;
            for (int r = 0; r < m / 2; ++r) {
