var minFlips = function(grid) {
    const m = grid.length;
    const n = grid[0].length;
    let ans = 0;

    for (let r = 0; r < Math.floor(m / 2); r++) {
        for (let c = 0; c < Math.floor(n / 2); c++) {
            const ones = grid[r][c] + grid[m - 1 - r][c] + grid[r][n - 1 - c] + grid[m - 1 - r][n - 1 - c];
            ans += Math.min(ones, 4 - ones);
        }
    }

    let diff = 0;
    let onesPairs = 0;

    if (m % 2 === 1) {
        const midR = Math.floor(m / 2);
        for (let c = 0; c < Math.floor(n / 2); c++) {
            if (grid[midR][c] !== grid[midR][n - 1 - c]) {
                diff++;
            } else if (grid[midR][c] === 1) {
                onesPairs++;
            }
        }
    }

    if (n % 2 === 1) {
        const midC = Math.floor(n / 2);
        for (let r = 0; r < Math.floor(m / 2); r++) {
            if (grid[r][midC] !== grid[m - 1 - r][midC]) {
                diff++;
            } else if (grid[r][midC] === 1) {
                onesPairs++;
            }
        }
    }

    ans += diff;
    if (onesPairs % 2 === 1 && diff === 0) {
        ans += 2;
    }

    if (m % 2 === 1 && n % 2 === 1) {
        if (grid[Math.floor(m / 2)][Math.floor(n / 2)] === 1) {
            ans += 1;
        }
    }

    return ans;
};
